import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem81 preserva operação e identidade sem prometer segurança infantil',()=>{for(const [id,titulo] of [['Hd0FWwNPR8uVXWLwPz3A','Carrinho Controle Remoto Recarregavel Storm Racer Turbo Potente Luz Led Alta Velocidade Preto Amorelancia'],['hDRgi7LAJobY4o5W9ipJ','Jogo 6 Copos Diamond Egipcio 300ml Vidro Grosso Diamante Luxo Transparente Vitrex'],['HEP91TkP4BHCEvBWmTHq','Honeywhale Rm2 Pro Patinete Elétrico Infantil, 70w-10km/h-11km, Motor-velocidade-autonomia, Triciclo Elétrico Dobrável Com Luzes De Led E Bluetooth, Scooter Para Crianças A Partir De 3 Anos, Rosa']]){const p={id,titulo,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/segur[oa]|aderência garantida|cristal confirmado|3 anos/i);}const r=correctProductData({id:'HEP91TkP4BHCEvBWmTHq',titulo:'Patinete infantil Honeywhale RM2 Pro rosa — idade de uso a confirmar'});assert.match(r.comentario,/50 W nominais de 70 W de pico/);assert.doesNotMatch(r.comentario,/8 km/);});
